/**
 * Formats one urgent ticket for chat.
 * Mode: Run Once for All Items.
 */
const ICON = { urgent: '\u{1F6A8}', security: '\u{1F512}' };

return $input.all().map((item) => {
  const t = item.json.body.ticket;
  const icon = t.category === 'security' ? ICON.security : ICON.urgent;
  const confidence = Math.round((t.confidence ?? 0) * 100);
  const lines = [
    `${icon} ${t.priority.toUpperCase()} ticket #${t.id}`,
    t.subject,
    '',
    `Category: ${t.category}  ·  Sentiment: ${t.sentiment}`,
    `AI confidence: ${confidence}%  ·  Routed to: ${t.routed_to}`,
    t.needs_human ? 'Flagged for human review before any automatic action.' : 'Auto-routed.',
  ];
  console.log(`[alert] ticket ${t.id} (${t.category}/${t.priority})`);
  return { json: { text: lines.join('\n'), ticket_id: t.id } };
});

/**
 * Builds the morning digest from /api/stats.
 * Mode: Run Once for All Items.
 */
const stats = $input.first().json;
const t = stats.tickets ?? {};
const top = (stats.by_category ?? []).slice(0, 4).map((c) => `  ${c.category}: ${c.n}`);
const urgent = (stats.by_priority ?? []).find((p) => p.priority === 'urgent')?.n ?? 0;

const lines = [
  '\u{1F4CA} Harbor Desk — overnight summary',
  '',
  `Tickets triaged: ${t.triaged ?? 0} of ${t.total ?? 0}`,
  `Waiting on a human: ${t.human_review ?? 0}`,
  `Urgent: ${urgent}`,
  '',
  'Top categories:',
  ...top,
];

console.log('[digest]', { triaged: t.triaged, human_review: t.human_review, urgent });
return [{ json: { text: lines.join('\n') } }];
